 static String rect(Object o){if(o==null)return "null";Rectangle2D r=(Rectangle2D)o;return "["+r.getX()+","+r.getY()+","+r.getWidth()+","+r.getHeight()+"]";}
 static String line(Line2D l){return "["+l.getX1()+","+l.getY1()+","+l.getX2()+","+l.getY2()+"]";}
