 static boolean selected(Object beam)throws Exception{Rectangle b=(Rectangle)call(beam,"getBounds");return b.x>=560&&b.x<620&&b.y>=987&&b.y<1015;}
 static String neighborhood(Object sys,Object point)throws Exception{java.util.List<String> rows=new ArrayList<>();for(Object s:(java.util.List<?>)call(sys,"getStavesAround",point))rows.add("{\"staff\":"+call(s,"getId")+",\"part\":"+call(call(s,"getPart"),"getId")+",\"part_area_bounds\":"+rect(call(call(s,"getPart"),"getAreaBounds"))+"}");return "["+String.join(",",rows)+"]";}
